INSERT INTO VX_CustomerTag (id, externalUserid, userid, tagId, tagName, source, batchNo, status, errmsg, tagAction, createTime) SELECT item.id, item.externalUserid, item.userid, item.tagId, item.tagName, item.source, item.batchNo, ISNULL(item.status, 1), item.errmsg, ISNULL(item.tagAction, 'ADD'), GETDATE() FROM ( VALUES
(#{item.id}, #{item.externalUserid}, #{item.userid}, #{item.tagId}, #{item.tagName}, #{item.source}, #{item.batchNo}, #{item.status}, #{item.errmsg}, #{item.tagAction})
) AS item(id, externalUserid, userid, tagId, tagName, source, batchNo, status, errmsg, tagAction) WHERE ISNULL(item.status, 1) <> 1 OR ISNULL(item.tagAction, 'ADD') <> 'ADD' OR NOT EXISTS ( SELECT 1 FROM VX_CustomerTag t WHERE t.externalUserid = item.externalUserid AND t.userid = item.userid AND t.tagId = item.tagId AND t.status = 1 AND t.tagAction = 'ADD' )
